import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum View {
  DASHBOARD = 'DASHBOARD',
  SCHEDULE = 'SCHEDULE',
  DETAILS = 'DETAILS',
  CHECKIN = 'CHECKIN'
}

export interface Meeting {
  id: string;
  title: string;
  startTime: string;
  endTime: string;
  organizer: string;
  type: 'INTERNAL' | 'CLIENT';
  isOngoing?: boolean;
}

export interface RoomStatus {
  isAvailable: boolean;
  currentMeeting?: Meeting;
  nextMeeting?: Meeting;
  name: string;
  location: string;
  capacity: number;
}

import { Meeting, RoomStatus } from './types';

export const MOCK_MEETINGS: Meeting[] = [
  {
    id: '1',
    title: 'Quarterly Strategic Planning',
    startTime: '10:00 AM',
    endTime: '11:30 AM',
    organizer: 'Sarah Chen',
    type: 'INTERNAL',
    isOngoing: true
  },
  {
    id: '2',
    title: 'Weekly Client Sync',
    startTime: '12:00 PM',
    endTime: '01:00 PM',
    organizer: 'Alex Rivera',
    type: 'CLIENT'
  },
  {
    id: '3',
    title: 'Design Review',
    startTime: '02:00 PM',
    endTime: '03:30 PM',
    organizer: 'Mike D.',
    type: 'INTERNAL'
  }
];

export const ROOM_INFO: RoomStatus = {
  name: 'Executive Boardroom',
  location: 'Building A • Floor 3 • Room 302',
  isAvailable: false,
  capacity: 12,
  currentMeeting: MOCK_MEETINGS[0],
  nextMeeting: MOCK_MEETINGS[1]
};

import React, { useState, useEffect } from 'react';
import { View } from './types';
import DashboardView from './components/DashboardView';
import ScheduleView from './components/ScheduleView';
import DetailsView from './components/DetailsView';
import CheckInOutView from './components/CheckInOutView';
import BottomNav from './components/BottomNav';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  const renderView = () => {
    switch (currentView) {
      case View.DASHBOARD:
        return <DashboardView currentTime={currentTime} />;
      case View.SCHEDULE:
        return <ScheduleView />;
      case View.DETAILS:
        return <DetailsView onBack={() => setCurrentView(View.DASHBOARD)} />;
      case View.CHECKIN:
        return <CheckInOutView onBack={() => setCurrentView(View.DASHBOARD)} currentTime={currentTime} />;
      default:
        return <DashboardView currentTime={currentTime} />;
    }
  };

  // The CheckInOutView is usually a separate full-screen tablet mode, 
  // but for this dashboard we integrate it as a view.
  // When in CheckIn view, we might hide the bottom nav for a more dedicated tablet feel.
  const showBottomNav = currentView !== View.CHECKIN;

  return (
    <div className="flex flex-col min-h-screen max-w-xl mx-auto border-x border-white/5 bg-background-light dark:bg-background-dark relative overflow-hidden">
      {renderView()}
      {showBottomNav && <BottomNav activeView={currentView} setView={setCurrentView} />}
    </div>
  );
};

export default App;

import React, { useState } from 'react';

interface CheckInOutViewProps {
  onBack: () => void;
  currentTime: Date;
}

const CheckInOutView: React.FC<CheckInOutViewProps> = ({ onBack, currentTime }) => {
  const [code, setCode] = useState<string>('');
  const [showFeedback, setShowFeedback] = useState(false);

  const handleKeyPress = (num: string) => {
    if (code.length < 4) {
      setCode(prev => prev + num);
    }
  };

  const handleBackspace = () => {
    setCode(prev => prev.slice(0, -1));
  };

  const handleCheckOut = () => {
    setShowFeedback(true);
  };

  return (
    <div className="flex flex-col h-full bg-background-dark overflow-hidden relative">
      {/* Custom Header for tablet feel */}
      <header className="flex items-center bg-background-dark p-4 border-b border-slate-800 justify-between">
        <button onClick={onBack} className="p-2 text-slate-400 hover:text-white transition-colors">
          <span className="material-symbols-outlined">arrow_back</span>
        </button>
        <div className="flex items-center gap-2">
          <span className="material-symbols-outlined text-primary text-2xl">schedule</span>
          <span className="text-lg font-bold text-white">
            {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
          </span>
        </div>
        <h2 className="text-lg font-bold text-white flex-1 text-center pr-10">Conference Room A</h2>
        <div className="w-8" />
      </header>

      <main className="flex-1 flex flex-col items-center justify-start p-6 overflow-y-auto custom-scrollbar">
        <div className="mt-4 mb-8">
          <div className="inline-flex items-center px-4 py-1.5 rounded-full bg-emerald-500/10 text-emerald-500 border border-emerald-500/20 text-sm font-semibold">
            <span className="w-2 h-2 rounded-full bg-emerald-500 mr-2"></span>
            Room Available
          </div>
        </div>

        <div className="text-center mb-10">
          <h1 className="text-3xl font-bold tracking-tight mb-2 text-white">Welcome</h1>
          <p className="text-slate-400">Please check in or out for your scheduled meeting</p>
        </div>

        <div className="grid grid-cols-1 gap-4 w-full mb-12 max-w-sm">
          <button className="flex flex-col items-center justify-center p-8 rounded-xl bg-primary text-white shadow-lg shadow-primary/20 hover:brightness-110 transition-transform active:scale-95">
            <span className="material-symbols-outlined text-4xl mb-3">login</span>
            <span className="text-xl font-bold">Check In</span>
          </button>
          <button 
            onClick={handleCheckOut}
            className="flex flex-col items-center justify-center p-8 rounded-xl bg-slate-800 border border-slate-700 hover:bg-slate-700 transition-transform active:scale-95"
          >
            <span className="material-symbols-outlined text-4xl mb-3 text-primary">logout</span>
            <span className="text-xl font-bold text-white">Check Out</span>
          </button>
        </div>

        <div className="w-full max-w-xs">
          <h4 className="text-slate-400 text-sm font-bold uppercase tracking-wider text-center mb-4">Enter Guest Code</h4>
          <div className="flex justify-center gap-3 mb-8">
            {[0, 1, 2, 3].map((idx) => (
              <div 
                key={idx}
                className={`flex h-14 w-12 items-center justify-center rounded-lg bg-slate-800 border-2 transition-all ${
                  code.length === idx ? 'border-primary ring-1 ring-primary/20' : 'border-slate-700'
                } text-xl font-bold text-white`}
              >
                {code[idx] ? '•' : ''}
              </div>
            ))}
          </div>

          <div className="grid grid-cols-3 gap-4">
            {['1', '2', '3', '4', '5', '6', '7', '8', '9', '', '0', 'delete'].map((key, i) => (
              key === '' ? <div key={i} /> : (
                <button
                  key={i}
                  onClick={() => key === 'delete' ? handleBackspace() : handleKeyPress(key)}
                  className={`h-16 flex items-center justify-center rounded-lg text-xl font-bold transition-colors ${
                    key === 'delete' 
                      ? 'text-slate-500 hover:text-primary' 
                      : 'bg-slate-800 text-white border border-slate-700 hover:bg-slate-700 active:bg-slate-600'
                  }`}
                >
                  {key === 'delete' ? <span className="material-symbols-outlined">backspace</span> : key}
                </button>
              )
            ))}
          </div>
        </div>

        <div className="mt-8 mb-12 flex items-center gap-2 text-primary font-semibold cursor-pointer hover:underline">
          <span className="material-symbols-outlined">qr_code_scanner</span>
          <span>Tap to Scan QR</span>
        </div>
      </main>

      {/* Feedback Modal Overlay */}
      {showFeedback && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-slate-900 w-full max-w-sm rounded-2xl shadow-2xl p-6 flex flex-col items-center">
            <div className="w-16 h-1 bg-slate-700 rounded-full mb-6" />
            <h3 className="text-2xl font-bold mb-2 text-white">Check-out Complete</h3>
            <p className="text-slate-400 text-center mb-8">How was your meeting experience?</p>

            <div className="flex justify-between w-full mb-8">
              <ReactionButton emoji="🤩" label="Excellent" />
              <ReactionButton emoji="🙂" label="Good" />
              <ReactionButton emoji="☹️" label="Poor" />
            </div>

            <div className="w-full mb-6">
              <textarea 
                className="w-full bg-slate-800 border-none rounded-lg p-4 text-sm text-white focus:ring-2 focus:ring-primary h-24 resize-none placeholder:text-slate-600" 
                placeholder="Any comments? (Optional)"
              />
            </div>

            <button 
              onClick={() => setShowFeedback(false)}
              className="w-full bg-primary text-white font-bold py-4 rounded-xl shadow-lg shadow-primary/30 active:scale-[0.98] transition-all"
            >
              Submit Feedback
