const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  const renderView = () => {
    switch (currentView) {
      case View.DASHBOARD:
        return <DashboardView currentTime={currentTime} />;
      case View.SCHEDULE:
        return <ScheduleView />;
      case View.DETAILS:
        return <DetailsView onBack={() => setCurrentView(View.DASHBOARD)} />;
      case View.CHECKIN:
        return <CheckInOutView onBack={() => setCurrentView(View.DASHBOARD)} currentTime={currentTime} />;
      default:
        return <DashboardView currentTime={currentTime} />;
    }
  };

  const showBottomNav = currentView !== View.CHECKIN;

  return (
    <div className="flex flex-col min-h-screen w-full bg-background-light dark:bg-background-dark relative overflow-hidden">
