      });
      const nextMeeting = MOCK_MEETINGS
        .filter(m => parseTimeString(m.startTime) > now)
        .sort((a, b) => parseTimeString(a.startTime).getTime() - parseTimeString(b.startTime).getTime())[0];

      setRoomStatus(prev => ({
        ...prev,
        isAvailable: !currentMeeting,
        currentMeeting: currentMeeting || undefined,
        nextMeeting: nextMeeting || undefined
      }));
      setIsSyncing(false);
    }, 800);
  }, []);

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    updateRoomStatus();
    const pollInterval = setInterval(updateRoomStatus, 15000);
    return () => clearInterval(pollInterval);
  }, [updateRoomStatus]);

  const renderView = () => {
    switch (currentView) {
      case View.DASHBOARD:
        return (
          <DashboardView 
            currentTime={currentTime} 
            roomStatus={roomStatus} 
            isSyncing={isSyncing} 
            layout={homeLayout} 
            onOpenSettings={() => setIsSettingsOpen(true)}
          />
        );
      case View.SCHEDULE:
        return <ScheduleView />;
      case View.DETAILS:
        return <DetailsView onBack={() => setCurrentView(View.DASHBOARD)} />;
      case View.CHECKIN:
        return <CheckInOutView onBack={() => setCurrentView(View.DASHBOARD)} currentTime={currentTime} />;
      default:
        return <DashboardView currentTime={currentTime} roomStatus={roomStatus} isSyncing={isSyncing} layout={homeLayout} onOpenSettings={() => setIsSettingsOpen(true)} />;
    }
  };

  const showBottomNav = currentView !== View.CHECKIN;

  return (
    <div className="flex flex-col min-h-screen w-full bg-[#050505] relative overflow-hidden font-display selection:bg-primary/30">
      <div className="fixed top-[-10%] left-[-10%] w-[40%] h-[40%] bg-primary/5 blur-[120px] rounded-full pointer-events-none" />
      <div className="fixed bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-primary/5 blur-[120px] rounded-full pointer-events-none" />

      <div className="flex-1 flex flex-col relative z-10 w-full h-screen mx-auto">
        {renderView()}
      </div>

      {showBottomNav && <BottomNav activeView={currentView} setView={setCurrentView} />}

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        currentLayout={homeLayout} 
        onSelectLayout={setHomeLayout} 
      />
    </div>
  );
};

