import React, { useState, useEffect, useCallback } from 'react';
import { View, RoomStatus, HomeLayout } from './types';
import DashboardView from './components/DashboardView';
import ScheduleView from './components/ScheduleView';
import DetailsView from './components/DetailsView';
import CheckInOutView from './components/CheckInOutView';
import BottomNav from './components/BottomNav';
import SettingsModal from './components/SettingsModal';
import { ROOM_INFO, MOCK_MEETINGS } from './constants';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.DASHBOARD);
  const [homeLayout, setHomeLayout] = useState<HomeLayout>(() => {
    const saved = localStorage.getItem('homeLayout');
    return (saved as HomeLayout) || HomeLayout.SPLIT_SCREEN;
  });
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [roomStatus, setRoomStatus] = useState<RoomStatus>(ROOM_INFO);
  const [isSyncing, setIsSyncing] = useState(false);

  useEffect(() => {
    localStorage.setItem('homeLayout', homeLayout);
  }, [homeLayout]);

  const parseTimeString = (timeStr: string) => {
    const [time, modifier] = timeStr.split(' ');
    let [hours, minutes] = time.split(':').map(Number);
    if (modifier === 'PM' && hours < 12) hours += 12;
    if (modifier === 'AM' && hours === 12) hours = 0;
    const date = new Date();
    date.setHours(hours, minutes, 0, 0);
    return date;
  };

  const updateRoomStatus = useCallback(() => {
    setIsSyncing(true);
    setTimeout(() => {
      const now = new Date();
      const currentMeeting = MOCK_MEETINGS.find(m => {
        const start = parseTimeString(m.startTime);
        const end = parseTimeString(m.endTime);
        return now >= start && now <= end;
      });
      const nextMeeting = MOCK_MEETINGS
        .filter(m => parseTimeString(m.startTime) > now)
        .sort((a, b) => parseTimeString(a.startTime).getTime() - parseTimeString(b.startTime).getTime())[0];

      setRoomStatus(prev => ({
        ...prev,
        isAvailable: !currentMeeting,
        currentMeeting: currentMeeting || undefined,
        nextMeeting: nextMeeting || undefined
      }));
      setIsSyncing(false);
    }, 800);
  }, []);

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    updateRoomStatus();
    const pollInterval = setInterval(updateRoomStatus, 15000);
    return () => clearInterval(pollInterval);
  }, [updateRoomStatus]);

  const renderView = () => {
    switch (currentView) {
      case View.DASHBOARD:
        return (
          <DashboardView 
            currentTime={currentTime} 
            roomStatus={roomStatus} 
            isSyncing={isSyncing} 
            layout={homeLayout} 
            onOpenSettings={() => setIsSettingsOpen(true)}
          />
        );
      case View.SCHEDULE:
        return <ScheduleView />;
      case View.DETAILS:
        return <DetailsView onBack={() => setCurrentView(View.DASHBOARD)} />;
      case View.CHECKIN:
        return <CheckInOutView onBack={() => setCurrentView(View.DASHBOARD)} currentTime={currentTime} />;
      default:
        return <DashboardView currentTime={currentTime} roomStatus={roomStatus} isSyncing={isSyncing} layout={homeLayout} onOpenSettings={() => setIsSettingsOpen(true)} />;
    }
  };

  const showNav = currentView !== View.CHECKIN;

  return (
    <div className="flex h-screen w-full bg-[#050505] relative overflow-hidden font-display selection:bg-primary/30">
      <div className="fixed top-[-10%] left-[-10%] w-[40%] h-[40%] bg-primary/5 blur-[120px] rounded-full pointer-events-none" />
      <div className="fixed bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-primary/5 blur-[120px] rounded-full pointer-events-none" />

      {/* Main Container - Adjusted for Sidebar */}
      <div className={`flex flex-row flex-1 w-full h-full relative z-10 transition-all duration-500 ${showNav ? 'pl-20 md:pl-24' : ''}`}>

        {showNav && <BottomNav activeView={currentView} setView={setCurrentView} />}

        <div className="flex-1 h-full overflow-hidden">
          {renderView()}
        </div>
      </div>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        currentLayout={homeLayout} 
        onSelectLayout={setHomeLayout} 
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { RoomStatus } from '../../types';
import { MOCK_MEETINGS } from '../../constants';

interface LayoutProps {
  currentTime: Date;
  roomStatus: RoomStatus;
  onOpenSettings: () => void;
}

const SplitScreenLayout: React.FC<LayoutProps> = ({ currentTime, roomStatus, onOpenSettings }) => {
  const [isScheduleOpen, setIsScheduleOpen] = useState(false);
  // Using ReturnType<typeof setTimeout> instead of NodeJS.Timeout to fix the 'Cannot find namespace NodeJS' error in browser environments.
  const autoCloseTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const formattedTime = currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  const formattedDate = currentTime.toLocaleDateString([], { weekday: 'long', month: 'short', day: 'numeric' });

  // Filter out the current meeting to show upcoming ones
  const upcomingMeetings = MOCK_MEETINGS.filter(m => m.id !== roomStatus.currentMeeting?.id);

  const resetAutoCloseTimer = () => {
    if (autoCloseTimerRef.current) {
      clearTimeout(autoCloseTimerRef.current);
    }
    if (isScheduleOpen) {
      autoCloseTimerRef.current = setTimeout(() => {
        setIsScheduleOpen(false);
      }, 60000); // 1 minute
    }
  };

  useEffect(() => {
    if (isScheduleOpen) {
      resetAutoCloseTimer();
    } else {
      if (autoCloseTimerRef.current) clearTimeout(autoCloseTimerRef.current);
    }
    return () => {
      if (autoCloseTimerRef.current) clearTimeout(autoCloseTimerRef.current);
    };
  }, [isScheduleOpen]);

  // Reset timer on any user activity within the component when schedule is open
  const handleUserActivity = () => {
    if (isScheduleOpen) {
      resetAutoCloseTimer();
    }
  };

  return (
    <div 
      className="flex h-screen w-full bg-[#050505] overflow-hidden text-white font-display relative"
      onMouseMove={handleUserActivity}
      onClick={handleUserActivity}
      onKeyDown={handleUserActivity}
    >
      {/* Left: Room Image Section (42% width) */}
      <div className="relative w-[42%] h-full shrink-0 overflow-hidden border-r border-white/5">
        <div 
          className="absolute inset-0 bg-cover bg-center transition-transform duration-[20s] hover:scale-105"
          style={{ backgroundImage: 'url("https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&q=80&w=1200")' }}
        />
        <div className="absolute inset-0 bg-gradient-to-t from-black via-black/20 to-transparent" />

        {/* TOP CENTER: Status Badge */}
        <div className="absolute top-12 left-1/2 -translate-x-1/2 z-20">
          <div className="flex flex-col items-center gap-4">
            <div className="flex flex-col items-center gap-3">
              <div className="relative">
                <div className={`absolute inset-0 rounded-full animate-ping opacity-20 duration-1000 ${
                  roomStatus.isAvailable ? 'bg-status-available' : 'bg-status-busy'
                }`} />
                <div className={`absolute -inset-2 rounded-full animate-pulse opacity-10 ${
                  roomStatus.isAvailable ? 'bg-status-available' : 'bg-status-busy'
                }`} />

                <div className={`relative size-16 rounded-full flex items-center justify-center border-2 shadow-[0_0_30px_rgba(0,0,0,0.5)] backdrop-blur-xl ${
                  roomStatus.isAvailable 
                  ? 'bg-status-available/30 border-status-available/50 text-status-available' 
                  : 'bg-status-busy/30 border-status-busy/50 text-status-busy'
                }`}>
                  <span className="material-symbols-outlined font-variation-fill text-3xl">
                    {roomStatus.isAvailable ? 'check_circle' : 'sensors'}
                  </span>
                </div>
              </div>

              <div className={`${
                roomStatus.isAvailable ? 'bg-status-available' : 'bg-status-busy'
              } px-6 py-2 rounded-xl text-[14px] font-black uppercase tracking-[0.25em] shadow-[0_10px_25px_rgba(0,0,0,0.4)] border-t border-white/20`}>
                {roomStatus.isAvailable ? 'AVAILABLE' : 'IN USE'}
              </div>
            </div>

            {roomStatus.isAvailable && (
              <button 
                className="bg-white/10 backdrop-blur-xl border border-white/30 text-white px-8 py-3 rounded-2xl text-sm font-black uppercase tracking-[0.2em] shadow-[0_20px_40px_rgba(0,0,0,0.3)] hover:bg-white/20 hover:border-white/50 hover:scale-105 active:scale-95 transition-all flex items-center gap-2 group"
              >
                <span className="material-symbols-outlined text-lg font-bold group-hover:rotate-90 transition-transform duration-500">add</span>
                Book Now
              </button>
            )}
          </div>
        </div>

        {/* BOTTOM: Room Label */}
        <div className="absolute bottom-10 left-10 right-10">
          <h1 className="text-white text-[3.5vw] font-black tracking-tighter leading-none mb-3 drop-shadow-2xl uppercase text-center md:text-left">
            {roomStatus.name || 'EVEREST'}
          </h1>
          <div className="flex flex-col gap-1.5 text-slate-300">
            <div className="flex items-center gap-2 justify-center md:justify-start">
              <span className="material-symbols-outlined text-lg text-primary">location_on</span>
              <p className="text-sm lg:text-base font-bold uppercase tracking-[0.15em] opacity-90">Building A • Floor 2</p>
            </div>
            <p className="text-[11px] lg:text-[12px] font-black uppercase tracking-[0.3em] text-slate-500 text-center md:text-left md:pl-7">
              {roomStatus.location} • {roomStatus.capacity} Persons
            </p>
          </div>
        </div>
      </div>

      {/* Right: Dashboard Content */}
      <div className="relative flex-1 h-full flex flex-col bg-[#080808] p-8 lg:p-12 overflow-hidden">
        <div className="flex-1 flex flex-col justify-between overflow-hidden">

          {/* Header */}
          <div className="flex justify-between items-start shrink-0">
            <div className="flex flex-col">
              <h2 className="text-[72px] lg:text-[84px] xl:text-[96px] font-black leading-none tracking-tighter text-white">
                {formattedTime}
              </h2>
              <p className="text-slate-500 text-lg lg:text-xl font-black uppercase tracking-[0.3em] mt-1">
                {formattedDate}
              </p>
            </div>
            <button 
              onClick={onOpenSettings}
              className="size-12 lg:size-14 rounded-xl bg-white/5 border border-white/10 flex items-center justify-center hover:bg-white/10 transition-all group"
            >
              <span className="material-symbols-outlined text-slate-400 group-hover:text-white transition-all text-2xl">settings</span>
            </button>
          </div>

          {/* ONGOING SESSION */}
          <div className="flex flex-col gap-5 lg:gap-6 flex-1 justify-center py-4">
            <div className="flex items-center gap-3">
              <span className="size-1.5 rounded-full bg-primary shadow-[0_0_15px_rgba(19,127,236,1)]"></span>
              <p className="text-primary text-sm lg:text-base font-black uppercase tracking-[0.4em]">ONGOING SESSION</p>
            </div>
            <h3 className="text-white text-[40px] lg:text-[50px] xl:text-[64px] font-black leading-[1.1] tracking-tight max-w-2xl line-clamp-2">
              {roomStatus.currentMeeting?.title || 'Room Available'}
            </h3>
            <div className="flex flex-col gap-3 max-w-xl">
              <div className="bg-[#111] border border-white/5 rounded-2xl p-4 lg:p-5 flex items-center gap-5 group">
                <div className="size-12 rounded-xl bg-white/5 flex items-center justify-center text-primary border border-white/5">
                  <span className="material-symbols-outlined text-2xl font-variation-fill">schedule</span>
                </div>
                <div className="flex flex-col">
                  <p className="text-white text-xl lg:text-2xl font-black leading-tight">
                    {roomStatus.currentMeeting?.startTime} - {roomStatus.currentMeeting?.endTime}
                  </p>
                  <p className="text-slate-500 text-sm font-bold opacity-80 uppercase tracking-widest">Scheduled Duration</p>
                </div>
              </div>
              <div className="bg-[#111] border border-white/5 rounded-2xl p-4 lg:p-5 flex items-center gap-5 group">
                <div className="size-12 rounded-xl bg-white/5 flex items-center justify-center text-primary border border-white/5">
                  <span className="material-symbols-outlined text-2xl font-variation-fill">person</span>
                </div>
                <div className="flex flex-col">
                  <p className="text-white text-xl lg:text-2xl font-black leading-tight">
                    {roomStatus.currentMeeting?.organizer || 'System'}
                  </p>
                  <p className="text-slate-500 text-sm font-bold opacity-80 uppercase tracking-widest">Lead Project Manager</p>
                </div>
              </div>
            </div>
            <div className="flex items-center gap-4 mt-2">
              <button className="flex-1 bg-primary text-white py-4 lg:py-5 rounded-2xl text-lg lg:text-xl font-black shadow-[0_20px_40px_rgba(19,127,236,0.3)] hover:brightness-110 transition-all flex items-center justify-center gap-3 border-t border-white/20 disabled:opacity-50" disabled={roomStatus.isAvailable}>
                <span className="material-symbols-outlined text-2xl">more_time</span> Extend
              </button>
              <button className="flex-1 bg-[#1a1a1a] text-white py-4 lg:py-5 rounded-2xl text-lg lg:text-xl font-black border border-white/5 hover:bg-white/10 transition-all flex items-center justify-center gap-3 disabled:opacity-50" disabled={roomStatus.isAvailable}>
                <span className="material-symbols-outlined text-2xl">logout</span> End Now
              </button>
            </div>
          </div>

          {/* UP NEXT Section with Vertical Toggle */}
          <div className="flex flex-col gap-3 lg:gap-4 mt-auto">
            <p className="text-[#9dabb9] text-sm lg:text-base font-black uppercase tracking-[0.4em] px-2 opacity-60">UP NEXT</p>
            <div className="flex items-stretch gap-3">
              <div className="flex-1">
                {upcomingMeetings.slice(0, 1).map((meeting) => (
                  <div key={meeting.id} className="bg-[#111] border border-white/5 rounded-2xl p-5 lg:p-6 flex items-center justify-between group transition-all hover:bg-white/[0.03] h-full">
                    <div className="flex items-center gap-5">
                      <div className="size-14 rounded-2xl bg-[#1a1a1a] flex items-center justify-center text-slate-400 group-hover:text-primary transition-colors border border-white/5">
                        <span className="material-symbols-outlined text-2xl font-variation-fill">calendar_today</span>
                      </div>
                      <div className="flex flex-col">
                        <p className="text-white text-lg lg:text-xl font-black tracking-tight leading-none truncate max-w-[200px] lg:max-w-xs">{meeting.title}</p>
                        <p className="text-slate-500 font-bold text-sm lg:text-base mt-2">{meeting.startTime} • {meeting.organizer}</p>
                      </div>
                    </div>
                    <div className="flex flex-col items-center shrink-0 pr-1">
                      <span className="text-primary text-[10px] font-black uppercase leading-none mb-1">IN</span>
                      <span className="text-primary text-[28px] lg:text-[32px] font-black leading-none">30M</span>
                    </div>
                  </div>
                ))}
              </div>

              {/* VERTICAL EXTEND BUTTON */}
              <button 
                onClick={() => setIsScheduleOpen(true)}
                className="w-16 bg-white/5 border border-white/10 rounded-2xl flex flex-col items-center justify-center gap-3 hover:bg-white/10 hover:border-white/20 transition-all group shrink-0"
              >
                <div className="flex flex-col items-center gap-1.5">
                  <span className="material-symbols-outlined text-primary text-xl font-black group-hover:scale-110 transition-transform">event_note</span>
                  <div className="[writing-mode:vertical-lr] rotate-180 text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] group-hover:text-white transition-colors">
                    Next Bookings
                  </div>
                </div>
                <span className="material-symbols-outlined text-slate-500 text-sm group-hover:translate-x-1 transition-transform">chevron_right</span>
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* FULL SCHEDULE SLIDE-OVER (70% Width) */}
      <div 
        className={`fixed inset-y-0 right-0 z-50 w-[70%] bg-black/40 backdrop-blur-[60px] border-l border-white/10 shadow-[20px_0_100px_rgba(0,0,0,0.8)] transition-transform duration-700 ease-[cubic-bezier(0.23,1,0.32,1)] ${
          isScheduleOpen ? 'translate-x-0' : 'translate-x-full'
        }`}
      >
        {/* Decorative Light Leak */}
        <div className="absolute top-[-20%] right-[-20%] size-[80%] bg-primary/5 blur-[150px] rounded-full pointer-events-none" />

        <div className="h-full flex flex-col p-10 lg:p-16 relative z-10">
          <header className="flex items-center justify-between mb-16">
            <div className="flex flex-col">
              <div className="flex items-center gap-4 mb-2">
                <div className="size-12 rounded-2xl bg-primary/20 flex items-center justify-center text-primary border border-primary/20">
                  <span className="material-symbols-outlined text-3xl font-variation-fill">event_available</span>
                </div>
                <h2 className="text-4xl lg:text-5xl font-black text-white tracking-tighter">Full Schedule</h2>
              </div>
              <p className="text-slate-400 font-bold uppercase tracking-[0.3em] text-xs ml-16">Everest Boardroom • Today</p>
            </div>
            <button 
              onClick={() => setIsScheduleOpen(false)}
              className="size-16 rounded-[2rem] bg-white/5 border border-white/10 flex items-center justify-center hover:bg-white/10 transition-all hover:rotate-90 duration-500 group"
            >
              <span className="material-symbols-outlined text-3xl text-slate-400 group-hover:text-white">close</span>
            </button>
          </header>

          <div className="flex-1 overflow-y-auto custom-scrollbar pr-6">
            <div className="flex flex-col gap-6">
              {MOCK_MEETINGS.map((meeting, idx) => (
                <div 
                  key={meeting.id} 
                  className={`group flex items-center justify-between p-8 rounded-[3rem] border transition-all duration-500 hover:scale-[1.02] ${
                    idx === 0 
                      ? 'bg-primary/10 border-primary/30 ring-1 ring-primary/20' 
                      : 'bg-white/[0.02] border-white/5 hover:bg-white/[0.05] hover:border-white/10'
                  }`}
                  style={{ transitionDelay: `${idx * 100}ms` }}
                >
                  <div className="flex items-center gap-8">
                    <div className="flex flex-col items-center min-w-[80px]">
                      <span className="text-2xl font-black text-white leading-none tracking-tighter">{meeting.startTime.split(' ')[0]}</span>
                      <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest mt-1">{meeting.startTime.split(' ')[1]}</span>
                    </div>
                    <div className="h-10 w-px bg-white/10" />
                    <div className="flex flex-col">
                      {idx === 0 && (
                        <span className="bg-primary text-white text-[9px] font-black px-2 py-0.5 rounded-md uppercase tracking-widest mb-2 w-fit">Now Playing</span>
                      )}
                      <h4 className="text-2xl lg:text-3xl font-black text-white tracking-tight">{meeting.title}</h4>
                      <div className="flex items-center gap-3 mt-1.5 text-slate-400">
                        <p className="text-sm font-bold uppercase tracking-wider">{meeting.organizer}</p>
                        <span className="size-1 rounded-full bg-slate-700" />
                        <p className="text-sm font-medium">{meeting.startTime} - {meeting.endTime}</p>
                      </div>
                    </div>
                  </div>
                  <div className={`px-5 py-2 rounded-2xl text-[10px] font-black uppercase tracking-widest border transition-all ${
                    meeting.type === 'CLIENT' 
                    ? 'bg-purple-500/10 border-purple-500/20 text-purple-400 group-hover:bg-purple-500/20' 
                    : 'bg-slate-800/50 border-white/5 text-slate-400 group-hover:bg-slate-800'
                  }`}>
                    {meeting.type}
                  </div>
                </div>
              ))}

              {/* Empty state placeholder for gap */}
              <div className="flex items-center justify-center p-12 border-2 border-dashed border-white/5 rounded-[3rem] mt-6 opacity-40">
                <div className="flex flex-col items-center gap-3">
                   <span className="material-symbols-outlined text-5xl text-slate-600">more_horiz</span>
                   <p className="text-[10px] font-black uppercase tracking-[0.4em] text-slate-600">End of Schedule</p>
                </div>
              </div>
            </div>
          </div>

          <footer className="mt-16 pt-10 border-t border-white/5 flex items-center justify-between">
            <div className="flex flex-col">
              <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.3em]">Last Updated</p>
              <p className="text-white font-bold">{currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
            </div>
            <div className="flex items-center gap-2 px-4 py-2 bg-primary/10 rounded-full border border-primary/20">
              <span className="size-2 rounded-full bg-primary animate-pulse"></span>
              <span className="text-[9px] font-black text-primary uppercase tracking-[0.2em]">Auto-syncing active</span>
            </div>
          </footer>
        </div>
      </div>
    </div>
  );
};

export default SplitScreenLayout;
